        this.clientId = clientId;
        this.name = name;
        this.outstanding = outstanding;
    }

    public Long getClientId() {
        return clientId;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getOutstanding() {
        return outstanding;
    }
}

